// ===== open tasks as chips in the Farm view: add, switch, collapse, close =====
ST.done[0] = DF; ST.part[0] = PF; ST.todo[0] = PF; ST.look[0] = AF;
const CT = LT + 50;
const under = (h) => h.replace('top: ' + LT + 'px; max-height: calc(100% - ' + (LT + 12) + 'px);', 'top: ' + CT + 'px; max-height: calc(100% - ' + (CT + 12) + 'px);');
const TI = { rx: SC2.syr, vax: SHIELD, move: I.move || 'M4 12h16m-5-5 5 5-5 5' };
// the strip of open tasks: the active one outlined; each closes with ×; past four, the rest under +N
const chips = (list, on, more, menu) => card({ left: '12px', top: LT + 'px' }, list.map((x) => '<span style="' + st({ display: 'inline-flex', alignItems: 'center', gap: '7px', height: '32px', padding: '0 6px 0 10px', borderRadius: '9px', background: x[0] === on ? '#FFFFFF' : 'transparent', boxShadow: x[0] === on ? 'inset 0 0 0 1.5px ' + K.ink : 'none', fontSize: '13px', fontWeight: x[0] === on ? 600 : 500, color: K.ink, whiteSpace: 'nowrap' }) + '"><span style="display: inline-flex; color: ' + (x[2] === 'vax' ? K.green : K.blue) + ';">' + ic(TI[x[2]], 14) + '</span>' + x[1] + '<span style="display: inline-flex; color: ' + K.muted + '; padding: 3px;">' + ic(I.x, 12, 2.2) + '</span></span>').join('') + (more ? '<span style="' + st({ display: 'inline-flex', alignItems: 'center', gap: '4px', height: '32px', padding: '0 10px', borderRadius: '9px', background: menu ? K.press : 'transparent', fontSize: '13px', fontWeight: 500 }) + '">' + more + ic(I.down, 13, 2) + '</span>' : '') + (menu || ''), { display: 'flex', alignItems: 'center', gap: '2px', padding: '5px', background: 'rgba(255,255,255,.94)' });
// the card header with collapse (back to the plain map, the chip stays) and close
const theadC = (o) => thead(o).replace("fontSize: '17px', lineHeight: '22px'".replace(/x/,'x'), '').replace('font-size: 17px; line-height: 22px;', 'font-size: 15.5px; line-height: 21px; overflow: hidden; text-overflow: ellipsis;').replace('<span style="display: inline-flex; color: ' + K.muted + '; padding: 6px;">' + ic(I.x, 17) + '</span>', '<span title="Collapse" style="display: inline-flex; color: ' + K.muted + '; padding: 4px;">' + ic(I.down, 17) + '</span><span title="Close" style="display: inline-flex; color: ' + K.muted + '; padding: 4px;">' + ic(I.x, 17) + '</span>');
const rxCard = () => under(paneSlim(theadC({ title: 'Treatment RX-25G009', sub: 'Amoxicillin · dose 2 of 3 today' }), gauge([[DM, 'Given', 2], [PM, 'Due', 1], [LM, 'Skipped', 1]], 4, '2', 'of 4 sows') + '<div style="display: flex; gap: 8px; margin-top: 12px;">' + fbtn(ic(SC2.ext, 15) + '&nbsp; Open page') + '</div>'));
const vaxCard = () => under(paneSlim(theadC({ title: 'PRRS vaccine', sub: 'Batch 30 and 31 · 2 rooms', ico: SHIELD, icoBg: K.greenT, icoInk: K.green }), gauge([[DM, 'Vaccinated', 44], [PM, 'Due', 59], [LM, 'Skipped', 1]], 104, '44', 'of 104 pens') + sec('Rooms', 'pens left') + box([{ h: t('Nursery 1', { flex: 1, fontWeight: 500 }) + mu('16') + ic(I.chev, 14, 1.8, K.faint) }, { h: t('Nursery 2', { flex: 1, fontWeight: 500 }) + mu('44') + ic(I.chev, 14, 1.8, K.faint) }]) + '<div style="display: flex; gap: 8px; margin-top: 12px;">' + fbtn(ic(SC2.ext, 15) + '&nbsp; Open page') + '</div>'));
const two = [['rx', 'RX-25G009', 'rx'], ['vax', 'PRRS vaccine', 'vax']];
const five = [['rx', 'RX-25G009', 'rx'], ['vax', 'PRRS vaccine', 'vax'], ['mv', 'Move · Batch 33', 'move'], ['rx2', 'RX-25G014', 'rx']];
const ovMenu = '<div style="' + st({ position: 'absolute', right: '6px', top: '46px', width: '220px', padding: '6px', borderRadius: '12px', background: '#FFFFFF', boxShadow: '0 1px 2px rgba(17,21,17,.06), 0 12px 30px rgba(17,21,17,.16)' }) + '">' + [['rx', 'RX-25G011'], ['vax', 'Sampling · Batch 30']].map((x) => '<div style="display: flex; align-items: center; gap: 8px; height: 38px; padding: 0 8px; border-radius: 8px; font-size: 13px;"><span style="display: inline-flex; color: ' + K.blue + ';">' + ic(TI[x[0]], 14) + '</span><span style="flex: 1;">' + x[1] + '</span><span style="display: inline-flex; color: ' + K.muted + ';">' + ic(I.x, 12, 2.2) + '</span></div>').join('') + '</div>';
const d41under = () => under(d41c(null));

frames.k1 = { bg: 'tx', cap: 'Open a second task and it is added as a chip, never replacing the first. The active chip is outlined; its card shows and its pigs colour the map. The arrow collapses, × closes.', html: () => tabsStrip('Farm view') + fbar() + rxCard() + chips(two, 'rx') + vctl };
frames.k2 = { bg: 'v1', cap: 'Collapse (the arrow by ×, a click on empty map, or Esc): the card goes, the colours go, the map is the plain Farm view again. The tasks stay as chips; one click brings either back exactly as it was. Coming back to the Farm view later opens like this.', html: () => tabsStrip('Farm view') + fbar() + chips(two, '') + vctl };
frames.k3 = { bg: 'nv', cap: 'Click the other chip: the map flies to its rooms and takes its colours; its card replaces the first in the pane. One task colours the map at a time.', html: () => tabsStrip('Farm view') + fadeAll + penSvg() + nbar() + vaxCard() + chips(two, 'vax') + vctl };
frames.k4 = { bg: 'tx', cap: 'Many open: four chips, then +2 with the rest. × on a chip, or in its menu row, closes that task; nothing else does.', html: () => tabsStrip('Farm view') + fbar() + rxCard() + chips(five, 'rx', '+2', ovMenu) + vctl };
frames.k5 = { bg: 'tx', cap: 'A pen with one sow: clicking it goes straight to her view in this task; there is no pen step. A group pen zooms in and lines its pigs up instead.', html: () => tabsStrip('Farm view') + fbar() + chips(two, 'rx') + vctl + d41under() };
